new file mode 100644
index 0000000..3f5f4af
--- /dev/null
+++ b/internal/core/k8s/session.go
@@ -0,0 +1,130 @@
+package k8s
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"sort"
+
+	apierrors "k8s.io/apimachinery/pkg/api/errors"
+	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
+	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
+	"k8s.io/apimachinery/pkg/runtime/schema"
+)
+
+const (
+	LabelSession = "gitopsctl.io/session"
+	LabelAgent   = "gitopsctl.io/agent"
+)
+
+var (
+	namespaceGVR     = schema.GroupVersionResource{Version: "v1", Resource: "namespaces"}
+	resourceQuotaGVR = schema.GroupVersionResource{Version: "v1", Resource: "resourcequotas"}
+)
+
+var ErrNamespaceNotOwned = errors.New("namespace is not owned by this session")
+
+type SessionNamespace struct {
+	Name    string
+	Session string
+}
+
+type SessionNamespaceSpec struct {
+	Name    string
+	Session string
+	Agent   string
+	Quota   map[string]string
+}
+
+func sessionLabels(session, agent string) map[string]any {
+	labels := map[string]any{
+		LabelManagedBy: ManagerName,
+		LabelSession:   session,
+	}
+	if agent != "" {
+		labels[LabelAgent] = agent
+	}
+	return labels
+}
+
+// EnsureSessionNamespace creates the labelled namespace and its quota. An existing namespace is accepted only if it already belongs to the session.
+func (cs *ClientSet) EnsureSessionNamespace(ctx context.Context, spec SessionNamespaceSpec) error {
+	ns := &unstructured.Unstructured{Object: map[string]any{
+		"apiVersion": "v1",
+		"kind":       "Namespace",
+		"metadata":   map[string]any{"name": spec.Name, "labels": sessionLabels(spec.Session, spec.Agent)},
+	}}
+	_, err := cs.dynamicClient.Resource(namespaceGVR).Create(ctx, ns, metav1.CreateOptions{})
+	switch {
+	case apierrors.IsAlreadyExists(err):
+		if _, ownErr := cs.ownedNamespace(ctx, spec.Name, spec.Session); ownErr != nil {
+			return ownErr
+		}
+	case err != nil:
+		return fmt.Errorf("create namespace %s: %w", spec.Name, err)
+	}
+
+	if len(spec.Quota) == 0 {
+		return nil
+	}
+	hard := make(map[string]any, len(spec.Quota))
+	for resource, quantity := range spec.Quota {
+		hard[resource] = quantity
+	}
+	quota := &unstructured.Unstructured{Object: map[string]any{
+		"apiVersion": "v1",
+		"kind":       "ResourceQuota",
+		"metadata":   map[string]any{"name": "gitopsctl-session", "namespace": spec.Name, "labels": sessionLabels(spec.Session, spec.Agent)},
+		"spec":       map[string]any{"hard": hard},
+	}}
+	if _, err := cs.dynamicClient.Resource(resourceQuotaGVR).Namespace(spec.Name).Create(ctx, quota, metav1.CreateOptions{}); err != nil && !apierrors.IsAlreadyExists(err) {
+		return fmt.Errorf("create resource quota in %s: %w", spec.Name, err)
+	}
+	return nil
+}
+
+// DeleteSessionNamespace deletes the namespace only when it carries this session's labels; a missing namespace is success.
+func (cs *ClientSet) DeleteSessionNamespace(ctx context.Context, name, session string) error {
+	ns, err := cs.ownedNamespace(ctx, name, session)
+	if apierrors.IsNotFound(err) {
+		return nil
+	}
+	if err != nil {
+		return err
+	}
+	uid := ns.GetUID()
+	err = cs.dynamicClient.Resource(namespaceGVR).Delete(ctx, name, metav1.DeleteOptions{Preconditions: &metav1.Preconditions{UID: &uid}})
+	if err != nil && !apierrors.IsNotFound(err) {
+		return fmt.Errorf("delete namespace %s: %w", name, err)
+	}
+	return nil
+}
+
+func (cs *ClientSet) ownedNamespace(ctx context.Context, name, session string) (*unstructured.Unstructured, error) {
+	ns, err := cs.dynamicClient.Resource(namespaceGVR).Get(ctx, name, metav1.GetOptions{})
+	if err != nil {
+		if apierrors.IsNotFound(err) {
+			return nil, err
+		}
+		return nil, fmt.Errorf("get namespace %s: %w", name, err)
+	}
+	labels := ns.GetLabels()
+	if labels[LabelManagedBy] != ManagerName || labels[LabelSession] != session {
+		return nil, fmt.Errorf("%w: %s", ErrNamespaceNotOwned, name)
+	}
+	return ns, nil
+}
+
+// SessionNamespaces lists every namespace this controller created for a session.
+func (cs *ClientSet) SessionNamespaces(ctx context.Context) ([]SessionNamespace, error) {
+	list, err := cs.dynamicClient.Resource(namespaceGVR).List(ctx, metav1.ListOptions{LabelSelector: LabelManagedBy + "=" + ManagerName + "," + LabelSession})
+	if err != nil {
+		return nil, fmt.Errorf("list session namespaces: %w", err)
+	}
+	namespaces := make([]SessionNamespace, 0, len(list.Items))
+	for _, item := range list.Items {
+		namespaces = append(namespaces, SessionNamespace{Name: item.GetName(), Session: item.GetLabels()[LabelSession]})
+	}
+	sort.Slice(namespaces, func(i, j int) bool { return namespaces[i].Name < namespaces[j].Name })
+	return namespaces, nil
+}
diff --git a/internal/core/k8s/session_test.go b/internal/core/k8s/session_test.go
new file mode 100644
index 0000000..848641b
--- /dev/null
+++ b/internal/core/k8s/session_test.go
@@ -0,0 +1,127 @@
+package k8s
+
+import (
+	"context"
+	"errors"
+	"testing"
+
+	"go.uber.org/zap"
+	apierrors "k8s.io/apimachinery/pkg/api/errors"
+	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
+	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
+	"k8s.io/apimachinery/pkg/runtime"
+	"k8s.io/apimachinery/pkg/runtime/schema"
+	dynamicfake "k8s.io/client-go/dynamic/fake"
+)
+
+func sessionClientSet() *ClientSet {
+	client := dynamicfake.NewSimpleDynamicClientWithCustomListKinds(runtime.NewScheme(), map[schema.GroupVersionResource]string{
+		namespaceGVR:     "NamespaceList",
+		resourceQuotaGVR: "ResourceQuotaList",
+	})
+	return &ClientSet{logger: zap.NewNop(), dynamicClient: client}
+}
+
+func rawNamespace(name string, labels map[string]string) *unstructured.Unstructured {
+	ns := &unstructured.Unstructured{Object: map[string]any{
+		"apiVersion": "v1", "kind": "Namespace", "metadata": map[string]any{"name": name},
+	}}
+	ns.SetLabels(labels)
+	return ns
+}
+
+func TestEnsureSessionNamespace_CreatesLabelledNamespaceAndQuota(t *testing.T) {
+	cs := sessionClientSet()
+	err := cs.EnsureSessionNamespace(context.Background(), SessionNamespaceSpec{Name: "agent-a-1", Session: "s1", Agent: "a", Quota: map[string]string{"pods": "5"}})
+	if err != nil {
+		t.Fatal(err)
+	}
+	ns, err := cs.dynamicClient.Resource(namespaceGVR).Get(context.Background(), "agent-a-1", metav1.GetOptions{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	labels := ns.GetLabels()
+	if labels[LabelManagedBy] != ManagerName || labels[LabelSession] != "s1" || labels[LabelAgent] != "a" {
+		t.Fatalf("unexpected labels %v", labels)
+	}
+	if _, err := cs.dynamicClient.Resource(resourceQuotaGVR).Namespace("agent-a-1").Get(context.Background(), "gitopsctl-session", metav1.GetOptions{}); err != nil {
+		t.Fatalf("quota missing: %v", err)
+	}
+}
+
+func TestEnsureSessionNamespace_IsIdempotentForOwnSession(t *testing.T) {
+	cs := sessionClientSet()
+	spec := SessionNamespaceSpec{Name: "agent-a-1", Session: "s1", Quota: map[string]string{"pods": "5"}}
+	for i := 0; i < 2; i++ {
+		if err := cs.EnsureSessionNamespace(context.Background(), spec); err != nil {
+			t.Fatalf("attempt %d: %v", i, err)
+		}
+	}
+}
+
+func TestEnsureSessionNamespace_RefusesForeignNamespace(t *testing.T) {
+	cs := sessionClientSet()
+	if _, err := cs.dynamicClient.Resource(namespaceGVR).Create(context.Background(), rawNamespace("agent-a-1", map[string]string{"team": "payments"}), metav1.CreateOptions{}); err != nil {
+		t.Fatal(err)
+	}
+	err := cs.EnsureSessionNamespace(context.Background(), SessionNamespaceSpec{Name: "agent-a-1", Session: "s1"})
+	if !errors.Is(err, ErrNamespaceNotOwned) {
+		t.Fatalf("expected ErrNamespaceNotOwned, got %v", err)
+	}
+}
+
+func TestDeleteSessionNamespace(t *testing.T) {
+	ctx := context.Background()
+	cs := sessionClientSet()
+	owned := map[string]string{LabelManagedBy: ManagerName, LabelSession: "s1"}
+	for name, labels := range map[string]map[string]string{
+		"owned":         owned,
+		"other-session": {LabelManagedBy: ManagerName, LabelSession: "s2"},
+		"unlabelled":    nil,
+	} {
+		if _, err := cs.dynamicClient.Resource(namespaceGVR).Create(ctx, rawNamespace(name, labels), metav1.CreateOptions{}); err != nil {
+			t.Fatal(err)
+		}
+	}
+
+	if err := cs.DeleteSessionNamespace(ctx, "owned", "s1"); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := cs.dynamicClient.Resource(namespaceGVR).Get(ctx, "owned", metav1.GetOptions{}); !apierrors.IsNotFound(err) {
+		t.Fatalf("owned namespace should be gone, got %v", err)
+	}
+	for _, name := range []string{"other-session", "unlabelled"} {
+		if err := cs.DeleteSessionNamespace(ctx, name, "s1"); !errors.Is(err, ErrNamespaceNotOwned) {
+			t.Fatalf("%s: expected ErrNamespaceNotOwned, got %v", name, err)
+		}
+		if _, err := cs.dynamicClient.Resource(namespaceGVR).Get(ctx, name, metav1.GetOptions{}); err != nil {
+			t.Fatalf("%s must survive: %v", name, err)
+		}
+	}
+	if err := cs.DeleteSessionNamespace(ctx, "never-existed", "s1"); err != nil {
+		t.Fatalf("missing namespace should be success, got %v", err)
+	}
+}
+
+func TestSessionNamespaces_ListsOnlyManagedSessions(t *testing.T) {
+	ctx := context.Background()
+	cs := sessionClientSet()
+	for name, labels := range map[string]map[string]string{
+		"b": {LabelManagedBy: ManagerName, LabelSession: "s2"},
+		"a": {LabelManagedBy: ManagerName, LabelSession: "s1"},
+		"x": {LabelManagedBy: ManagerName},
+		"y": {LabelSession: "s9"},
+		"z": nil,
+	} {
+		if _, err := cs.dynamicClient.Resource(namespaceGVR).Create(ctx, rawNamespace(name, labels), metav1.CreateOptions{}); err != nil {
+			t.Fatal(err)
+		}
+	}
+	got, err := cs.SessionNamespaces(ctx)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(got) != 2 || got[0] != (SessionNamespace{"a", "s1"}) || got[1] != (SessionNamespace{"b", "s2"}) {
+		t.Fatalf("unexpected namespaces %v", got)
+	}
+}
